<template>
  <div class="co-page">
    <header v-if="set && !review && !replacing" class="co-topbar">
      <div class="co-mode-tabs" role="tablist" aria-label="Étape du test">
        <button class="co-mode-tab" :class="{ active: view === 'overview' }" :disabled="view === 'practice'" @click="view = 'overview'">
          Série <span class="co-mode-count">{{ set.questions.length }}</span>
        </button>
        <button class="co-mode-tab" :class="{ active: view === 'practice' }" :disabled="view !== 'overview'" @click="start">
          {{ attempt?.status === 'in-progress' || attempt?.status === 'paused' ? 'Reprendre' : 'Entraînement' }}
        </button>
        <button class="co-mode-tab" :class="{ active: view === 'results' }" disabled>Résultats</button>
      </div>
      <div class="co-timer" :class="{ running: view === 'practice' && !paused, warning: view === 'practice' && elapsed >= benchmark * .8 && elapsed <= benchmark, over: view === 'practice' && elapsed > benchmark }">
        <span aria-hidden="true">⏱</span>
        <strong>{{ fmt(view === 'practice' ? elapsed : (result?.elapsedSeconds || attempt?.elapsedSeconds || 0)) }}</strong>
        <span>/ {{ fmt(benchmark) }}</span>
        <span class="co-timer-status">{{ view === 'practice' ? (paused ? 'En pause' : elapsed > benchmark ? 'Temps dépassé' : 'En cours') : 'Temps repère' }}</span>
      </div>
    </header>

    <p v-if="error" class="co-alert danger" role="alert">{{ error }}</p>
    <section v-if="loading" class="co-card co-loading" aria-live="polite">Chargement des données locales…</section>

    <section v-else-if="review" class="co-card">
      <header class="co-card-head"><div><span class="co-eyebrow">Import</span><h2>Vérifier la série</h2></div><span class="co-badge info">Avant enregistrement</span></header>
      <p class="co-lead"><strong>{{ review.title }}</strong></p>
      <div class="co-meta"><span>{{ review.parsed.questionCount }} questions</span><span>{{ review.parsed.correctionCount }} corrections</span><span>{{ review.audioCount }} MP3</span><span>{{ review.parsed.images.length }} images</span><span>{{ review.durationLabel }} d’audio</span></div>
      <ul class="co-review-list">
        <li v-for="q in review.parsed.questions" :key="q.number">
          <span class="co-question-number">Q{{ q.number }}</span><span>{{ q.audio?.file.name || 'Audio manquant' }}</span><span class="co-badge" :class="complete(q) ? 'success' : 'muted'">{{ complete(q) ? 'Prête' : 'Ignorée' }}</span>
        </li>
      </ul>
      <div v-if="review.blockers.length" class="co-alert danger" role="alert"><strong>Import impossible</strong><ul><li v-for="x in review.blockers" :key="x">{{ x }}</li></ul></div>
      <details v-if="review.warnings.length" class="co-details"><summary>{{ review.warnings.length }} avertissement(s)</summary><ul><li v-for="x in review.warnings" :key="x">{{ x }}</li></ul></details>
      <div class="co-actions"><button class="co-btn primary" :disabled="review.blockers.length" @click="commitImport">Importer le test</button><button class="co-btn secondary" @click="review = null">Annuler</button></div>
    </section>

    <section v-else-if="!set || replacing" class="co-card co-import" @dragover.prevent @drop.prevent="onDrop">
      <span class="co-import-icon" aria-hidden="true">📁</span><span class="co-eyebrow">Compréhension orale</span><h2>Importer une série</h2>
      <p>Déposez un dossier contenant un fichier Markdown et les MP3 numérotés, y compris dans des sous-dossiers.</p>
      <div class="co-actions center"><label class="co-picker primary">Choisir un dossier<input type="file" webkitdirectory multiple @change="selectFiles"></label><label class="co-picker secondary">Choisir des fichiers<input type="file" multiple accept=".md,.mp3,audio/*" @change="selectFiles"></label></div>
      <button v-if="set" class="co-btn ghost" @click="replacing = false">Annuler le remplacement</button>
      <small>Stockage local uniquement · les archives ne sont pas prises en charge.</small>
    </section>

    <section v-else-if="view === 'overview'" class="co-card">
      <header class="co-card-head"><div><span class="co-eyebrow">Série d’entraînement</span><h2>{{ set.title }}</h2></div><span class="co-badge info">{{ set.questions.length }} questions</span></header>
      <div class="co-meta"><span>Audio {{ fmt(totalDuration) }}</span><span>Temps repère {{ fmt(benchmark) }}</span><span>Stockée sur cet appareil</span></div>
      <p class="co-lead">Écoutez chaque extrait, sélectionnez une réponse puis terminez le test pour afficher le corrigé.</p>
      <div class="co-actions"><button class="co-btn primary" @click="start">{{ attempt?.status === 'in-progress' || attempt?.status === 'paused' ? '▶ Reprendre la tentative' : '▶ Commencer' }}</button><button class="co-btn secondary" @click="replaceMode">Remplacer le dossier</button><button class="co-btn ghost danger" @click="removeSet">Supprimer ce test</button></div>
      <details v-if="set.validationWarnings?.length" class="co-details"><summary>Avertissements d’import</summary><ul><li v-for="w in set.validationWarnings" :key="w">{{ w }}</li></ul></details>
      <div v-if="history.length" class="co-history"><h3>Historique</h3><ul><li v-for="h in history" :key="h.id"><div><strong>{{ new Date(h.submittedAt).toLocaleDateString('fr-FR') }}</strong><small>{{ new Date(h.submittedAt).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) }} · {{ fmt(h.elapsedSeconds) }}</small></div><span class="co-badge info">{{ h.correct }}/{{ h.total }} · {{ h.score }}/699</span></li></ul></div>
    </section>

    <template v-else-if="view === 'practice'">
      <div class="co-practice-status"><div><strong>{{ answered }}/{{ set.questions.length }} réponses</strong><span class="co-badge" :class="paused ? 'warning' : 'success'">{{ paused ? 'En pause' : 'Audio actif' }}</span></div><div class="co-actions"><button class="co-btn secondary" @click="togglePause">{{ paused ? '▶ Reprendre' : '⏸ Pause' }}</button><button class="co-btn danger-solid" @click="submit">Terminer et corriger</button></div></div>
      <p v-if="elapsed > benchmark" class="co-alert warning" role="status">Temps indicatif dépassé — le chronomètre continue.</p>
      <nav class="co-question-nav" aria-label="Questions"><button v-for="(q, i) in set.questions" :key="q.number" :class="{ current: i === current, answered: attempt.answers[q.number] }" :aria-current="i === current ? 'step' : undefined" :aria-label="`Question ${q.number}, ${attempt.answers[q.number] ? 'répondue' : 'sans réponse'}`" @click="go(i)">{{ q.number }}</button></nav>
      <section class="co-card co-question">
        <header class="co-card-head"><div><span class="co-eyebrow">Question {{ question.number }} sur {{ set.questions.length }}</span><h2>Écoutez puis choisissez une réponse</h2></div><span class="co-badge" :class="attempt.answers[question.number] ? 'success' : 'muted'">{{ attempt.answers[question.number] ? 'Répondue' : 'Sans réponse' }}</span></header>
        <img v-if="urls[question.imageAssetId]" class="co-image" :src="urls[question.imageAssetId]" :alt="`Illustration de la question ${question.number}`">
        <div class="co-audio"><audio ref="audio" :src="urls[question.audioAssetId]" controls preload="metadata" :aria-label="`Lire l’audio de la question ${question.number}`" @play="audioPlay" @pause="audioPause" @timeupdate="audioTime" @ended="audioEnded"></audio><button class="co-btn secondary" @click="replay">↺ Rejouer</button><small>{{ question.audioFileName }} · {{ fmt(question.audioDurationSeconds) }} · {{ playback.playCount }} lecture(s)</small></div>
        <p v-if="countdown !== null" class="co-countdown" aria-live="polite">Prochaine question dans {{ Math.ceil(countdown) }} s · intervalle d’entraînement</p>
        <fieldset class="co-options"><legend class="sr-only">Réponse à la question {{ question.number }}</legend><label v-for="letter in letters" :key="letter" class="co-option" :class="{ selected: attempt.answers[question.number] === letter }"><input v-model="attempt.answers[question.number]" type="radio" :name="`q${question.number}`" :value="letter" @change="persist"><b>{{ letter }}</b><span>{{ question.options[letter] }}</span></label></fieldset>
        <div class="co-actions spread"><button class="co-btn secondary" :disabled="current === 0" @click="go(current - 1)">← Précédente</button><button class="co-btn primary" :disabled="current === set.questions.length - 1" @click="go(current + 1)">Suivante →</button></div>
      </section>
    </template>

    <section v-else class="co-results">
      <div class="co-score-card"><span class="co-eyebrow">Résultat d’entraînement</span><div class="co-score-big">{{ result.correct }}/{{ result.total }}</div><p>{{ result.percent }} % · estimation {{ result.score }}/699</p><div class="co-meta center"><span>{{ result.answered }} réponses</span><span>{{ set.questions.length - result.answered }} sans réponse</span><span>{{ fmt(result.elapsedSeconds) }}</span></div><small>Ce résultat n’est pas un score officiel du TCF.</small><div class="co-actions center"><button class="co-btn primary" @click="restart">Refaire le test</button><button class="co-btn secondary" @click="view = 'overview'">Vue d’ensemble</button><button class="co-btn ghost" @click="replaceMode">Importer une autre série</button></div></div>
      <article v-for="q in set.questions" :key="q.number" class="co-card co-correction" :class="status(q) === 'Correcte' ? 'correct' : status(q) === 'Incorrecte' ? 'wrong' : 'skipped'">
        <header class="co-card-head"><span class="co-eyebrow">Question {{ q.number }}</span><span class="co-badge" :class="status(q) === 'Correcte' ? 'success' : status(q) === 'Incorrecte' ? 'danger' : 'muted'">{{ status(q) }}</span></header>
        <img v-if="urls[q.imageAssetId]" class="co-image" :src="urls[q.imageAssetId]" :alt="`Illustration de la question ${q.number}`"><p v-if="q.prompt" class="co-lead"><strong>Question :</strong> {{ q.prompt }}</p>
        <ul class="co-result-options"><li v-for="l in letters" :key="l" :class="{ right: q.correctAnswer === l, user: result.answers[q.number] === l }"><b>{{ l }}</b><span>{{ q.options[l] }}</span><span v-if="q.correctAnswer === l" class="co-answer-tag correct">Réponse attendue</span><span v-if="result.answers[q.number] === l" class="co-answer-tag yours">Votre choix</span></li></ul>
        <audio :src="urls[q.audioAssetId]" controls preload="none" :aria-label="`Réécouter la question ${q.number}`" @play="exclusivePlay"></audio>
        <details v-if="q.transcript" open class="co-correction-panel"><summary>Transcription / corrigé</summary><p class="pre">{{ q.transcript }}</p></details><details v-if="q.reasoning" open class="co-correction-panel"><summary>Explication</summary><p>{{ q.reasoning }}</p></details><details v-if="q.vocabulary?.length" class="co-correction-panel"><summary>Vocabulaire à retenir ({{ q.vocabulary.length }})</summary><dl><template v-for="(v, i) in q.vocabulary" :key="i"><dt>{{ v.word }}</dt><dd>{{ v.definition }}<span v-if="v.lemmas.length"> — {{ v.lemmas.join(', ') }}</span></dd></template></dl></details>
      </article>
    </section>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { audioQuestionNumber, dataUrlToBlob, parseCoMarkdown } from '../../utils/coParser.js'
import { clearCoData, loadAsset, loadCoState, replaceCoSet, saveAttempt, saveHistory } from '../../utils/coStore.js'
const letters=['A','B','C','D'], ANSWER_INTERVAL=10
const loading=ref(true), error=ref(''), review=ref(null), set=ref(null), attempt=ref(null), history=ref([]), view=ref('overview'), current=ref(0), elapsed=ref(0), paused=ref(true), countdown=ref(null), result=ref(null), audio=ref(null), urls=ref({}), replacing=ref(false)
let timer=null, lastTick=0, countdownValue=null, activeAudio=null
const question=computed(()=>set.value.questions[current.value]), answered=computed(()=>Object.values(attempt.value?.answers||{}).filter(Boolean).length), benchmark=computed(()=>Math.round((set.value?.questions.length||0)*2100/39)), totalDuration=computed(()=>set.value?.questions.reduce((n,q)=>n+q.audioDurationSeconds,0)||0), playback=computed(()=>attempt.value.playback[question.value.number])
const fmt=n=>{const seconds=Math.max(0,Math.round(n||0));return`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
// Some official-style image items in the supplied manifests omit an answer key.
// Keep them playable (and clearly mark them non-noted) rather than losing their audio.
const complete=q=>letters.every(l=>q.options[l])&&q.audio
onMounted(async()=>{try{const s=await loadCoState();set.value=s.set;attempt.value=s.attempt;history.value=s.history;if(set.value)await makeUrls()}catch(e){error.value=`Stockage local indisponible : ${e.message}`}finally{loading.value=false}})
onBeforeUnmount(()=>{stopTick();revokeUrls();audio.value?.pause()})
async function makeUrls(){revokeUrls();for(const q of set.value.questions){for(const id of [q.audioAssetId,q.imageAssetId].filter(Boolean)){if(!urls.value[id]){const blob=await loadAsset(id);if(blob)urls.value[id]=URL.createObjectURL(blob)}}}}
function revokeUrls(){Object.values(urls.value).forEach(URL.revokeObjectURL);urls.value={}}
function selectFiles(e){processFiles([...e.target.files].map(file=>({file,path:file.webkitRelativePath||file.name})));e.target.value=''}
async function onDrop(e){const items=[...e.dataTransfer.items];const entries=items.map(i=>i.webkitGetAsEntry?.()).filter(Boolean);if(entries.some(x=>x.isDirectory)){const files=[];for(const x of entries)await walk(x,files);await processFiles(files)}else await processFiles([...e.dataTransfer.files].map(file=>({file,path:file.name})))}
async function walk(entry,out,path=''){if(entry.isFile)await new Promise(r=>entry.file(file=>{out.push({file,path:path+file.name});r()}));else{const reader=entry.createReader();let batch;do{batch=await new Promise((r,j)=>reader.readEntries(r,j));for(const child of batch)await walk(child,out,path+entry.name+'/')}while(batch.length)}}
async function duration(file){return new Promise(resolve=>{const a=new Audio(),url=URL.createObjectURL(file);a.preload='metadata';a.onloadedmetadata=()=>{URL.revokeObjectURL(url);resolve(Number.isFinite(a.duration)?a.duration:null)};a.onerror=()=>{URL.revokeObjectURL(url);resolve(null)};a.src=url})}
async function processFiles(files){error.value='';const md=files.filter(x=>/\.md$/i.test(x.file.name)), mp3=files.filter(x=>/\.mp3$/i.test(x.file.name)), unsupported=files.filter(x=>/\.(wav|m4a|aac|ogg|flac)$/i.test(x.file.name));const blockers=[];if(md.length!==1)blockers.push(md.length?'Plusieurs fichiers Markdown détectés : sélectionnez une seule série.':'Aucun fichier Markdown détecté.');if(unsupported.length)blockers.push(`Audio non pris en charge : ${unsupported.map(x=>x.path).join(', ')}`);let parsed={questions:[],images:[],warnings:[],blockers:[],questionCount:0,correctionCount:0};if(md.length===1)parsed=parseCoMarkdown(await md[0].file.text());blockers.push(...parsed.blockers);const candidates=new Map(), warnings=[...parsed.warnings];for(const x of mp3){const n=audioQuestionNumber(x.path);if(n){if(!candidates.has(n))candidates.set(n,[]);candidates.get(n).push(x)}else warnings.push(`MP3 non mappé : ${x.path}`)}const questionNumbers=new Set(parsed.questions.map(q=>q.number));for(const [number,list] of candidates){if(!questionNumbers.has(number))warnings.push(`MP3 ignoré sans question ${number} : ${list.map(x=>x.path).join(', ')}`)}for(const q of parsed.questions){const list=(candidates.get(q.number)||[]).sort((a,b)=>a.path.localeCompare(b.path));if(list.length>1)warnings.push(`Question ${q.number} : doublons audio, ${list[0].path} conservé.`);if(list[0]){const d=await duration(list[0].file);if(d===null)warnings.push(`Question ${q.number} : MP3 illisible (${list[0].path}).`);else q.audio={...list[0],duration:d}}else warnings.push(`Question ${q.number} : audio manquant, elle sera ignorée.`)}const valid=parsed.questions.filter(complete);if(!valid.length)blockers.push('Aucune question complète et lisible ne peut être importée.');review.value={title:md[0]?.file.name.replace(/\.md$/i,'')||'Série CO',md:md[0],parsed,audioCount:mp3.length,warnings,blockers,valid,durationLabel:fmt(valid.reduce((n,q)=>n+q.audio.duration,0))}}
async function commitImport(){const skipped=review.value.parsed.questions.length-review.value.valid.length;if(skipped&&!confirm(`${skipped} question(s) invalide(s) ou sans audio seront ignorées. Continuer ?`))return;const id=`co-${Date.now()}`,assets=[];const questions=review.value.valid.map(q=>{const audioAssetId=`${id}-audio-${q.number}`,imageAssetId=q.image?`${id}-image-${q.number}`:null;assets.push({id:audioAssetId,blob:q.audio.file});if(q.image)assets.push({id:imageAssetId,blob:dataUrlToBlob(q.image.dataUrl)});return {...q,image:undefined,audio:undefined,imageAssetId,audioAssetId,audioFileName:q.audio.file.name,audioDurationSeconds:q.audio.duration}});const newSet={id,title:review.value.title,importedAt:Date.now(),sourceMarkdownName:review.value.md.file.name,questions,validationWarnings:review.value.warnings};try{await replaceCoSet(newSet,assets);set.value=newSet;attempt.value=null;history.value=[];review.value=null;replacing.value=false;await makeUrls();view.value='overview'}catch(e){const previous=await loadCoState();set.value=previous.set;attempt.value=previous.attempt;history.value=previous.history;review.value=null;replacing.value=false;if(set.value)await makeUrls();error.value=`Import non enregistré; l’ancienne série est conservée. ${e.message}`}}
function newAttempt(){return{id:`attempt-${Date.now()}`,setId:set.value.id,status:'in-progress',answers:Object.fromEntries(set.value.questions.map(q=>[q.number,null])),elapsedSeconds:0,startedAt:Date.now(),playback:Object.fromEntries(set.value.questions.map(q=>[q.number,{playCount:0,lastPositionSeconds:0}]))}}
async function start(){if(!attempt.value||attempt.value.status==='submitted')attempt.value=newAttempt();current.value=Math.max(0,set.value.questions.findIndex(q=>q.number===(attempt.value.currentQuestion||set.value.questions[0].number)));elapsed.value=attempt.value.elapsedSeconds||0;paused.value=false;view.value='practice';startTick();await nextTick();if(audio.value){audio.value.currentTime=playback.value.lastPositionSeconds||0;audio.value.play().catch(()=>{})}}
function startTick(){stopTick();lastTick=performance.now();timer=setInterval(()=>{if(paused.value)return;const now=performance.now(),delta=(now-lastTick)/1000;lastTick=now;elapsed.value+=delta;if(countdown.value!==null){countdownValue-=delta;countdown.value=Math.max(0,countdownValue);if(countdownValue<=0)advanceAuto()}if(Math.floor(elapsed.value)%2===0)persist()},250)}
function stopTick(){clearInterval(timer);timer=null}
function persist(){if(!attempt.value)return;attempt.value.elapsedSeconds=Math.round(elapsed.value);attempt.value.currentQuestion=question.value?.number;attempt.value.status=paused.value?'paused':'in-progress';attempt.value.updatedAt=Date.now();saveAttempt(structuredClone(attempt.value)).catch(()=>{})}
function togglePause(){if(paused.value){paused.value=false;lastTick=performance.now();if(countdown.value===null)audio.value?.play().catch(()=>{})}else{paused.value=true;audio.value?.pause()}persist()}
function exclusivePlay(event){if(activeAudio&&activeAudio!==event.target)activeAudio.pause();activeAudio=event.target}
function audioPlay(event){exclusivePlay(event);if(paused.value){paused.value=false;lastTick=performance.now()}playback.value.playCount++;startTick();persist()}
function audioPause(){if(!audio.value?.ended){paused.value=true;persist()}}
function audioTime(){if(playback.value&&audio.value)playback.value.lastPositionSeconds=audio.value.currentTime}
function audioEnded(){playback.value.lastPositionSeconds=0;countdownValue=ANSWER_INTERVAL;countdown.value=ANSWER_INTERVAL;persist()}
async function advanceAuto(){countdown.value=null;if(current.value<set.value.questions.length-1){current.value++;await nextTick();audio.value?.play().catch(()=>{})}}
async function go(i){if(i<0||i>=set.value.questions.length)return;countdown.value=null;audio.value?.pause();current.value=i;paused.value=true;await nextTick();if(audio.value)audio.value.currentTime=playback.value.lastPositionSeconds||0;persist()}
function replay(){if(!audio.value)return;countdown.value=null;audio.value.currentTime=0;audio.value.play().catch(()=>{})}
async function submit(){const missing=set.value.questions.length-answered.value;if(missing&&!confirm(`${missing} question(s) sans réponse. Terminer quand même ?`))return;audio.value?.pause();paused.value=true;stopTick();const scorable=set.value.questions.filter(q=>q.correctAnswer);const correct=scorable.filter(q=>attempt.value.answers[q.number]===q.correctAnswer).length;result.value={answers:{...attempt.value.answers},correct,total:scorable.length,answered:answered.value,percent:scorable.length?Math.round(correct/scorable.length*100):0,score:scorable.length?Math.round(correct/scorable.length*699):0,elapsedSeconds:Math.round(elapsed.value)};attempt.value.status='submitted';attempt.value.submittedAt=Date.now();await saveAttempt(attempt.value);const record={id:attempt.value.id,setId:set.value.id,submittedAt:attempt.value.submittedAt,...result.value};await saveHistory(record);history.value.unshift(record);view.value='results'}
function status(q){if(!result.value.answers[q.number])return'Sans réponse';if(!q.correctAnswer)return'Non notée';return result.value.answers[q.number]===q.correctAnswer?'Correcte':'Incorrecte'}
function restart(){attempt.value=newAttempt();elapsed.value=0;current.value=0;paused.value=true;result.value=null;view.value='overview';saveAttempt(attempt.value)}
function replaceMode(){if(attempt.value?.status==='in-progress'&&!confirm('Remplacer cette série et abandonner la tentative en cours ?'))return;review.value=null;replacing.value=true;view.value='overview'}
async function removeSet(){if(!confirm('Supprimer la série, ses fichiers et tout son historique ?'))return;await clearCoData();revokeUrls();set.value=null;attempt.value=null;history.value=[]}
</script>

<style scoped>
.co-page { display: flex; flex-direction: column; gap: 14px; font-size: 13px; }
.co-topbar { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; }
.co-mode-tabs { display: flex; gap: 5px; padding: 4px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface-alt); }
.co-mode-tab { min-height: 38px; padding: 8px 12px; border: 0; border-radius: 8px; background: transparent; color: var(--text-muted); font-size: 13px; font-weight: 600; }
.co-mode-tab.active { color: #8e44ad; background: var(--surface); box-shadow: 0 1px 3px var(--shadow-sm); }
.co-mode-tab:disabled:not(.active) { opacity: .48; cursor: not-allowed; }
.co-mode-count { margin-left: 4px; padding: 1px 7px; border-radius: 8px; color: #8e44ad; background: #8e44ad22; font-size: 11px; }
.co-timer { display: inline-flex; align-items: center; gap: 6px; padding: 8px 12px; border: 1.5px solid var(--border); border-radius: 10px; background: var(--surface); font-variant-numeric: tabular-nums; }
.co-timer strong { font-size: 18px; }.co-timer > span:nth-child(3) { color: var(--text-faint); font-size: 12px; }
.co-timer.running { border-color: #27ae60; background: #27ae600d; }.co-timer.warning { border-color: #e67e22; background: #e67e220d; }.co-timer.over { border-color: #c0392b; background: #c0392b12; }
.co-timer-status { margin-left: 3px; padding: 3px 7px; border-radius: 7px; background: var(--surface-alt); color: var(--text-muted); font-size: 11px; font-weight: 700; }
.co-card { display: flex; flex-direction: column; gap: 12px; padding: 14px 16px; border: 1.5px solid var(--border); border-radius: 14px; background: var(--surface); }
.co-card-head { display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 8px; }.co-card-head h2 { margin-top: 2px; color: var(--title-color); font-size: 16px; line-height: 1.35; }
.co-eyebrow { color: #8e44ad; font-size: 11px; font-weight: 700; letter-spacing: .45px; text-transform: uppercase; }.co-lead { color: var(--text-secondary); font-size: 13.5px; line-height: 1.55; }
